<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { hotelApi } from '../../api'
import { errorMessage } from '../../api/client'
import StatusTag from '../../components/StatusTag.vue'
import type { HotelService, PartnerResource, Room, TravelProduct } from '../../types'

const loading = ref(false); const loadingData = ref(true); const rooms = ref<Room[]>([]); const services = ref<HotelService[]>([]); const resources = ref<PartnerResource[]>([]); const product = ref<TravelProduct | null>(null); const validation = ref<Record<string, unknown> | null>(null); const traceId = ref(''); const fallbackUsed = ref(false)
const form = reactive({ target_date: '', weather: 'RAIN', target_crowd: 'FAMILY', minimum_gross_margin: '0.20', visitor_budget: '700', theme: '雨天亲子非遗', room_inventory_id: 0, breakfast_id: 0, breakfast_qty: 3, late_id: 0, late_qty: 1, partner_id: 0, partner_qty: 3, preferred_price: '599' })
const candidateResources = computed(() => resources.value.filter((item) => item.package_enabled && item.status === 'AVAILABLE' && item.remaining_capacity > 0))
async function loadData() { loadingData.value = true; try { const [roomResponse, serviceResponse, resourceResponse] = await Promise.all([hotelApi.rooms(), hotelApi.services(), hotelApi.resources()]); rooms.value = roomResponse.data; services.value = serviceResponse.data; resources.value = resourceResponse.data; const target = rooms.value.find((item) => item.room_type === '亲子房') || rooms.value[0]; form.target_date = target?.available_date || ''; form.room_inventory_id = target?.id || 0; form.breakfast_id = services.value.find((item) => item.service_type === 'BREAKFAST')?.id || 0; form.late_id = services.value.find((item) => item.service_type === 'LATE_CHECKOUT')?.id || 0; form.partner_id = candidateResources.value.find((item) => item.resource_name.includes('非遗'))?.id || candidateResources.value[0]?.id || 0 } catch (e) { ElMessage.error(errorMessage(e)) } finally { loadingData.value = false } }
const selectedRoom = computed(() => rooms.value.find((item) => item.id === form.room_inventory_id)); const selectedPartner = computed(() => resources.value.find((item) => item.id === form.partner_id))
async function generate() { loading.value = true; product.value = null; try { const selections = [{ resource_type: 'HOTEL_SERVICE', resource_id: form.breakfast_id, quantity_per_package: form.breakfast_qty }, { resource_type: 'HOTEL_SERVICE', resource_id: form.late_id, quantity_per_package: form.late_qty }, { resource_type: 'PARTNER_RESOURCE', resource_id: form.partner_id, quantity_per_package: form.partner_qty }].filter((item) => item.resource_id > 0); const response = await hotelApi.generateProduct({ target_date: form.target_date, weather: form.weather, target_crowd: form.target_crowd, minimum_gross_margin: form.minimum_gross_margin, visitor_budget: form.visitor_budget, theme: form.theme, room_inventory_id: form.room_inventory_id, resource_selections: selections, preferred_price: form.preferred_price }); product.value = response.data.product; validation.value = response.data.validation; traceId.value = response.data.trace_id; fallbackUsed.value = response.data.fallback_used; ElMessage.success('候选产品生成成功，库存与财务由规则引擎校验') } catch (e) { ElMessage.error(errorMessage(e)) } finally { loading.value = false } }
async function publish() { if (!product.value) return; try { await hotelApi.productStatus(product.value.id, 'ON_SALE'); product.value.status = 'ON_SALE'; ElMessage.success('产品已模拟发布') } catch (e) { ElMessage.error(errorMessage(e)) } }
onMounted(loadData)
</script>

<template>
  <div class="page-head"><div><div class="eyebrow">AI-ASSISTED PACKAGING</div><h1>智能生成主题产品</h1><p>AI只负责主题、资源候选和文案；库存、成本、价格与毛利全部由后端确定性规则计算。</p></div><el-button plain @click="loadData">重载资源</el-button></div>
  <div v-if="loadingData" class="panel empty-state">正在读取真实房量、服务与合作资源…</div>
  <div v-else class="split-layout"><div class="panel sticky-panel"><div class="section-title" style="margin-top:0"><h2>产品约束</h2><span>输入经营目标</span></div><el-form label-position="top"><div class="form-grid"><el-form-item label="目标入住日期"><el-date-picker v-model="form.target_date" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item><el-form-item label="当前天气"><el-select v-model="form.weather" style="width:100%"><el-option label="小雨 RAIN" value="RAIN" /><el-option label="晴天 SUNNY" value="SUNNY" /><el-option label="多云 CLOUDY" value="CLOUDY" /></el-select></el-form-item><el-form-item label="目标客群"><el-select v-model="form.target_crowd" style="width:100%"><el-option label="亲子家庭" value="FAMILY" /><el-option label="情侣" value="COUPLE" /><el-option label="本地周末客" value="LOCAL" /></el-select></el-form-item><el-form-item label="最低毛利率"><el-input v-model="form.minimum_gross_margin"><template #append>%</template></el-input></el-form-item><el-form-item label="游客预算上限"><el-input v-model="form.visitor_budget"><template #prepend>¥</template></el-input></el-form-item><el-form-item label="价格策略锚点"><el-input v-model="form.preferred_price"><template #prepend>¥</template></el-input></el-form-item><el-form-item class="full" label="主题方向"><el-input v-model="form.theme" /></el-form-item><el-form-item class="full" label="临期房型"><el-select v-model="form.room_inventory_id" style="width:100%"><el-option v-for="item in rooms" :key="item.id" :label="`${item.room_type} · 余 ${item.available_count} 间 · 成本 ¥${item.accounting_cost}`" :value="item.id" /></el-select></el-form-item><el-form-item label="早餐 / 套"><el-select v-model="form.breakfast_id" style="width:100%"><el-option v-for="item in services.filter(s => s.service_type === 'BREAKFAST')" :key="item.id" :label="`${item.service_name} · 余 ${item.available_quantity}`" :value="item.id" /></el-select><el-input-number v-model="form.breakfast_qty" :min="1" style="margin-top:8px;width:100%" /></el-form-item><el-form-item label="延迟退房 / 套"><el-select v-model="form.late_id" style="width:100%"><el-option v-for="item in services.filter(s => s.service_type === 'LATE_CHECKOUT')" :key="item.id" :label="`${item.service_name} · 余 ${item.available_quantity}`" :value="item.id" /></el-select><el-input-number v-model="form.late_qty" :min="1" style="margin-top:8px;width:100%" /></el-form-item><el-form-item class="full" label="文化体验资源"><el-select v-model="form.partner_id" style="width:100%"><el-option v-for="item in candidateResources" :key="item.id" :label="`${item.resource_name} · 余 ${item.remaining_capacity} · 结算 ¥${item.settlement_price}`" :value="item.id" /></el-select><el-input-number v-model="form.partner_qty" :min="1" style="margin-top:8px;width:100%" /></el-form-item></div><el-button type="primary" size="large" :loading="loading" style="width:100%;margin-top:8px" @click="generate">✦ 生成候选产品</el-button></el-form><div v-if="selectedRoom && selectedPartner" class="muted" style="margin-top:14px;line-height:1.7">将使用 {{ selectedRoom.room_type }} 与 {{ selectedPartner.resource_name }}。后端会重新读取实时资源并校验日期、天气、客群、容量与毛利。</div></div>
    <div class="panel"><div v-if="!product" class="empty-state"><div><div style="font-size:36px;color:#b8d8ce">✦</div><p>填写左侧约束后，生成一套可审阅的杭州主题住宿产品。</p></div></div><template v-else><div class="product-card__top"><span class="eyebrow">候选产品 · {{ product.product_code }}</span><StatusTag :status="product.status" /></div><h2 style="font-size:28px;margin:16px 0 6px">{{ product.product_name }}</h2><p class="muted">{{ product.recommendation_reason }}</p><div class="result-highlight"><div><small>可售数量</small><strong>{{ product.sale_quantity }} 套</strong></div><div><small>单套成本</small><strong>¥{{ product.unit_cost }}</strong></div><div><small>建议售价</small><strong>¥{{ product.suggested_price }}</strong></div><div><small>毛利率</small><strong>{{ (Number(product.gross_margin) * 100).toFixed(2) }}%</strong></div></div><div class="section-title"><h2>套餐资源</h2><span>瓶颈：{{ product.bottleneck_resource }}</span></div><div class="product-card__resources"><span v-for="item in product.resources" :key="item.id">{{ item.resource_name }} × {{ item.quantity_per_package }}</span></div><div class="panel" style="box-shadow:none;background:#f7fbf8;margin-top:16px"><div class="muted">营销标题</div><strong>{{ product.marketing_title }}</strong><p class="muted" style="line-height:1.8">{{ product.marketing_content }}</p><div class="muted">风险提示</div><p class="danger-text" style="line-height:1.7">{{ product.risk_message }}</p></div><el-alert v-if="fallbackUsed" title="当前使用了Mock/降级结果，库存与财务仍已由规则引擎重新校验。" type="warning" show-icon /><div v-if="validation" class="muted" style="margin-top:14px">规则校验 trace_id：{{ traceId }} · 最低允许售价 ¥{{ String((validation.financials as Record<string, unknown>)?.minimumAllowedPrice || '') }}</div><div class="form-actions"><el-button @click="$router.push(`/hotel/products/${product?.id}`)">查看详情</el-button><el-button type="primary" :disabled="product.status !== 'DRAFT'" @click="publish">模拟发布</el-button></div></template></div></div>
</template>

